import hashlib

def hash_test(function_name, phrase):
    hash_func = getattr(hashlib, function_name)
    return hash_func(phrase.encode()).hexdigest()

def main():
    phrases = [
        ('Laura!... Bazooms!', '98767cec58ce4cdb6181ff97710bef2ef2684dbe5c3f9b8f847d2a4d3c1540f0'),
        ('WHOA, MAMA!', 'd3776e045781f2a916b1eb6ff941fed6087d2f6bc02ad130fae6b9cbbe57b2e6'),
        ('I hurt myself. Can you carry me home?', 'f99b946aa21aa9d953063e5ef55340e9e5e36072f1c16e6e75b892c640c03095')
    ]

    algorithms = hashlib.algorithms_guaranteed

    for phrase, expected_hash in phrases:
        for algorithm in algorithms:
            try:
                result = hash_test(algorithm, phrase)
                if result == expected_hash:
                    print(f"Match found! Algorithm: {algorithm}, Phrase: {phrase}")
                    break
            except Exception as e:
                pass

if __name__ == "__main__":
    main()

import hashlib
import string

def find_sha256_matches(target_hashes):
    results = {}
    characters = string.ascii_letters + string.digits + string.punctuation + string.whitespace

    for char in characters:
        sha256 = hashlib.sha256(char.encode()).hexdigest()
        for node, target in target_hashes.items():
            if sha256.startswith(target):
                results[node] = char
                print(f"Match found: {node} = '{char}' => {target}")

    return results

def main():
    target_hashes = {
        'n': '1d',
        'o': 'de',
        'p': '1b',
        'q': '00',
        'r': 'c3',
        's': '5b'
    }

    matches = find_sha256_matches(target_hashes)
    print("\nSummary of Matches:")
    for node, match in matches.items():
        print(f"{node} = '{match}'")

if __name__ == "__main__":
    main()

from pwn import *

def main():
    # Known arguments
    known_inputs = {
        'o': 'V',
        'p': 'n',
        'r': '@'
    }

    # Address and port of the server
    address = "misc.chal.csaw.io"
    port = 1337

    try:
        # Establish connection
        conn = remote(address, port)

        # Send inputs in the correct format
        for key, value in known_inputs.items():
            formatted_input = f"{key}={value}\n"
            conn.send(formatted_input)

        # Receive and print server response
        while True:
            response = conn.recvline(timeout=5).decode('utf-8')
            if not response:
                break
            print(response)

    except EOFError as e:
        print(f"Encountered EOFError: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        conn.close()

if __name__ == "__main__":
    main()
